import {lessons,allWords,kanaRows,comboRows} from './data.js';
import {openHandwriting,hasHandwriting} from './handwriting/handwriting.js';
import {cleanWritingProgress} from './handwriting/model.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={home:'<path d="m3 10 9-7 9 7v10H3Z"/><path d="M9 20v-7h6v7"/>',book:'<path d="M12 5v16M12 5C8 2 4 3 2 4v15c4-1 7-1 10 2 3-3 6-3 10-2V4c-4-1-7-1-10 1Z"/>',repeat:'<path d="M20 7H7a5 5 0 0 0 0 10h1m-4-4 4 4-4 4M4 7h13a5 5 0 0 1 0 10h-1M20 3l-4 4 4 4"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',sound:'<path d="M4 9h4l5-4v14l-5-4H4Zm13-2a7 7 0 0 1 0 10m3-13a11 11 0 0 1 0 16"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 1v3m0 16v3M1 12h3m16 0h3M4 4l2 2m12 12 2 2M4 20l2-2M18 6l2-2"/>',cup:'<path d="M5 9h12v7a6 6 0 0 1-12 0Zm12 1h2a3 3 0 0 1 0 6h-2M8 3v3m5-3v3M3 23h16"/>',bag:'<path d="M4 7h16l1 15H3ZM8 8V5a4 4 0 0 1 8 0v3"/>',pin:'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="3"/>',heart:'<path d="M12 21 3 12C-3 4 7-1 12 6c5-7 15-2 9 6Z"/>',check:'<path d="m5 12 4 4L20 5"/>',star:'<path d="m12 2 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1Z"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',leaf:'<path d="M20 3C4 0 0 15 8 18 17 23 22 13 20 3ZM4 22 17 8"/>'};
const icon=(n,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.book}</svg>`;
const defaults=()=>({version:1,furigana:'all',romaji:false,rate:0.85,voice:'',goal:10,progress:{},cards:{},saved:[],kana:{},writing:{},lastWriting:{h:'',k:''},activity:{},lastLesson:'meet'});
let state=defaults(),storageOK=true;
try{const raw=localStorage.getItem('hiyori-v1');if(raw)state=validate(JSON.parse(raw));}catch{storageOK=false;}
function validate(x){if(!x||x.version!==1||!x.progress||!x.cards||!Array.isArray(x.saved))throw Error('不是日和日語的進度檔案');const n=defaults();n.furigana=['all','tap','none'].includes(x.furigana)?x.furigana:'all';n.romaji=!!x.romaji;n.rate=[0.65,0.85,1].includes(x.rate)?x.rate:0.85;n.goal=[5,10,15].includes(x.goal)?x.goal:10;n.voice=typeof x.voice==='string'?x.voice:'';n.lastLesson=lessons.some(l=>l.id===x.lastLesson)?x.lastLesson:'meet';n.saved=x.saved.filter(id=>allWords.some(w=>w.id===id));for(const l of lessons){const p=x.progress[l.id];if(p&&Number.isInteger(p.step)&&p.step>=0&&p.step<=4)n.progress[l.id]={step:p.step,complete:!!p.complete};}for(const w of allWords){const c=x.cards[w.id];if(c&&Number.isFinite(c.due)&&Number.isFinite(c.interval)&&c.interval>=0)n.cards[w.id]={due:c.due,interval:Math.min(c.interval,365),reps:Number.isFinite(c.reps)?Math.max(0,Math.floor(c.reps)):0};}for(const [k,v]of Object.entries(x.kana||{})){if(typeof v==='boolean')n.kana[k]=v;}for(const [k,v]of Object.entries(x.activity||{})){if(/^\d{4}-\d{2}-\d{2}$/.test(k)&&Number.isFinite(v)&&v>=0)n.activity[k]=v;}n.writing=cleanWritingProgress(x.writing,kanaRows.flat().filter(k=>k?.group==='basic').flatMap(k=>[k.h,k.k]));for(const type of ['h','k']){const char=x.lastWriting?.[type];if(kanaRows.flat().some(k=>k?.group==='basic'&&k[type]===char))n.lastWriting[type]=char;}return n;}
function save(){try{localStorage.setItem('hiyori-v1',JSON.stringify(state));storageOK=true;}catch{storageOK=false;toast('瀏覽器無法保存進度，請到「我的」匯出備份。');}}
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
function activity(){state.activity[today()]=(state.activity[today()]||0)+1;save();}
let page='today',lesson=null,step=0,question=0,answer=null,quizDone=false,translate=true,breakdown=true,kanaType='h',kanaGroup='basic',kanaQuiz=null,review=null,flipped=false,voices=[],speechRun=0,selectedWords=new Set();
let toastTimer;
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
const dueIds=()=>Object.keys(state.cards).filter(id=>state.cards[id].due<=Date.now());
const ruby=(jp,read)=>read&&read!==jp?`<ruby lang="ja">${esc(jp)}<rt>${esc(read)}</rt></ruby>`:`<span lang="ja">${esc(jp)}</span>`;
const readMap=[...allWords.filter(w=>/[一-龯]/.test(w.jp)),{jp:'林',reading:'りん'},{jp:'葵',reading:'あおい'},{jp:'来ました',reading:'きました'}].sort((a,b)=>b.jp.length-a.jp.length);
function annotated(t){let out='',i=0;while(i<t.length){const w=readMap.find(w=>t.startsWith(w.jp,i));if(w){out+=`<span class="reading" tabindex="0">${ruby(w.jp,w.reading)}</span>`;i+=w.jp.length;}else{out+=esc(t[i++]);}}return out;}
const playButton=(t,label='聽發音')=>`<button class="sound" data-action="speak" data-text="${esc(t)}" aria-label="${esc(label)}" title="${esc(label)}">${icon('sound')}</button>`;
function refreshVoices(){voices=window.speechSynthesis?.getVoices().filter(v=>/^ja(?:-|_)/i.test(v.lang))||[];}
if('speechSynthesis'in window){refreshVoices();speechSynthesis.addEventListener('voiceschanged',refreshVoices);}
function stopSpeech(){speechRun++;window.speechSynthesis?.cancel();document.querySelectorAll('.speaking').forEach(e=>e.classList.remove('speaking'));}
function speak(text,el){stopSpeech();if(!('speechSynthesis'in window)){toast('這個瀏覽器不支援合成語音，請使用支援語音的瀏覽器。');return;}refreshVoices();if(!voices.length){toast('裝置尚未提供日文語音。請在系統語言設定安裝日文語音，或使用其他瀏覽器。');return;}const run=speechRun;const u=new SpeechSynthesisUtterance(text);u.lang='ja-JP';u.voice=voices.find(v=>v.voiceURI===state.voice)||voices[0];u.rate=state.rate;el?.classList.add('speaking');u.onend=()=>{if(run===speechRun)el?.classList.remove('speaking');};u.onerror=e=>{el?.classList.remove('speaking');if(!['canceled','interrupted'].includes(e.error))toast('語音播放失敗，請再試一次或到「我的」切換聲音。');};speechSynthesis.speak(u);}
function nav(p){stopSpeech();$('#detail').close();page=p;lesson=null;review=null;render();window.scrollTo(0,0);}
function render(){document.body.dataset.furigana=state.furigana;const due=dueIds().length;$('#app').innerHTML=`<aside class="sidebar"><a class="brand" href="#today" data-nav="today"><span class="brand-mark">日</span><span>日和日語<small>HIYORI JAPANESE</small></span></a><div class="nav-caption">你的日語日常</div><nav>${[['today','home','今日學習'],['kana','book','五十音'],['courses','cup','情境課程'],['review','repeat','每日複習'],['mine','user','我的學習']].map(([id,i,t])=>`<button data-nav="${id}" class="nav-item ${page===id?'active':''}">${icon(i)}<span>${t}</span>${id==='review'&&due?`<b>${due}</b>`:''}</button>`).join('')}</nav><div class="sidebar-note">${icon('leaf')}<p>每天一點，<br>日語更近。</p><small>あせらず、一歩ずつ。</small></div><div class="local-note"><span class="dot"></span> 進度保存在此瀏覽器</div></aside><div class="workspace"><header><div class="breadcrumb">我的學習空間 <span>/</span> <b>${{today:'今日學習',kana:'五十音',courses:'情境課程',review:'每日複習',mine:'我的學習'}[page]}</b></div><div class="header-tools"><label class="furi-label">振假名 <select id="furigana" aria-label="振假名顯示"><option value="all" ${state.furigana==='all'?'selected':''}>全部顯示</option><option value="tap" ${state.furigana==='tap'?'selected':''}>需要時顯示</option><option value="none" ${state.furigana==='none'?'selected':''}>全部隱藏</option></select></label><button class="avatar" data-nav="mine" aria-label="我的學習">日</button></div></header><main>${page==='today'?home():page==='kana'?kanaPage():page==='courses'?(lesson?lessonPage():courses()):page==='review'?reviewPage():mine()}</main><footer><span>日和日語 · 讓日文，走進日常</span><span>語音由裝置合成提供</span></footer></div>`;}
function heading(eyebrow,title,sub){return `<div class="page-heading"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p class="muted">${sub}</p></div><span class="date-label">${new Intl.DateTimeFormat('zh-TW',{month:'long',day:'numeric',weekday:'short'}).format(new Date())}</span></div>`;}
function art(){return `<svg class="hero-art" viewBox="0 0 430 280" fill="none" aria-hidden="true"><circle cx="280" cy="113" r="90" fill="#e8bd8f" opacity=".45"/><path d="M155 220c55-5 126-4 212 4" stroke="#c4a78a" stroke-width="2"/><path d="M314 191c-12-48-9-85 5-123m-9 65c-37-10-47-29-35-44 28 0 40 23 35 44Zm3-22c27-1 45-15 39-34-26-3-41 13-39 34Z" fill="#849475"/><path d="M286 164h58l-8 57h-41Z" fill="#b56f51"/><path d="m96 192 90-21 91 32-93 24-88-27Z" fill="#557568"/><path d="m96 182 90-21 91 32-93 24-88-27Z" fill="#f8f3e5" stroke="#557568" stroke-width="2"/><path d="m184 176 1 32m-71-22 50-12m-39 20 38-10" stroke="#c8c1a8" stroke-width="2"/><path d="M191 132h61v39c0 31-61 31-61 0Z" fill="#faf7e9"/><path d="M251 142h10c21 0 21 29 0 29h-9" stroke="#faf7e9" stroke-width="9"/><ellipse cx="221" cy="132" rx="30" ry="8" fill="#d7b395"/><ellipse cx="221" cy="133" rx="24" ry="5" fill="#8f6750"/><path d="M211 114c-13-16 9-20 0-36m21 35c-13-16 9-20 0-36" stroke="#fffaf0" stroke-width="3" stroke-linecap="round"/><g transform="rotate(-12 125 105)"><rect x="85" y="57" width="70" height="85" rx="9" fill="#fffdf5"/><text x="120" y="116" text-anchor="middle" fill="#31594a" font-size="47" font-family="serif">あ</text></g><path d="m166 55 4 8 9 1-7 6 2 9-8-5-8 5 2-9-7-6 9-1Z" fill="#c78051"/></svg>`;}
function home(){const l=lessons.find(l=>l.id===state.lastLesson)||lessons[0],p=state.progress[l.id],done=lessons.filter(l=>state.progress[l.id]?.complete).length,known=Object.keys(state.kana).length;const n=state.activity[today()]||0;return `${heading('A LITTLE JAPANESE, EVERY DAY','こんにちは，今天也一起學日文。','不急著學會所有，一天一點就很好。')}<section class="hero"><div class="hero-content"><span class="pill">${done||p?'接續你的日語旅程':'從第一句日文開始'} <span>・ 初級 N5 入門</span></span><h2>${done||p?l.title:'把「初次見面」，<br>變成新的開始。'}</h2><p>${l.desc}<br>今天，試著${l.goal}。</p><button class="primary" data-start="${l.id}">${p?'繼續學習':done?'開始下一課':'開始第一課'} ${icon('arrow')}</button><span class="hero-time">${icon('clock')} 約 ${l.time} 分鐘</span></div>${art()}<span class="hero-caption">小さな一歩、大きな世界。</span></section><div class="stats"><div>${icon('book')}<span><small>已完成課程</small><strong>${done}<em> / 5 課</em></strong></span></div><div>${icon('repeat')}<span><small>今日待複習</small><strong>${dueIds().length}<em> 個詞語</em></strong></span></div><div>${icon('leaf')}<span><small>練習過的假名</small><strong>${known}<em> 個</em></strong></span></div><div>${icon('sun')}<span><small>累計學習日</small><strong>${Object.keys(state.activity).length}<em> 天</em></strong></span></div></div><div class="home-grid"><div><div class="section-title"><h2>今天，從這裡開始</h2><span>一點練習，一點進步</span></div><div class="quick-grid"><button class="quick-card" data-nav="review"><span class="tile-icon sage">${icon('repeat')}</span><h3>讓學過的，留在記憶裡</h3><p>${dueIds().length?`今天有 ${dueIds().length} 個詞語等你複習。`:'完成課程，把新詞語加入複習。'}</p><span class="text-link">${dueIds().length?'開始複習':'看看複習卡'} ${icon('arrow')}</span></button><button class="quick-card" data-nav="kana"><span class="tile-icon sand kana-icon">あ</span><h3>和五十音再熟悉一點</h3><p>聽一聽、點一點，從聲音認識日文。</p><span class="text-link">練習五十音 ${icon('arrow')}</span></button></div><div class="section-title lower"><h2>把日文帶進生活</h2><button class="text-link" data-nav="courses">所有課程 ${icon('arrow')}</button></div><div class="mini-courses">${lessons.slice(1,3).map(l=>`<button class="mini-course" data-start="${l.id}"><span class="tile-icon ${l.color}">${icon(l.icon)}</span><span><small>${l.category}</small><h3>${l.short}</h3><p>初級 · ${l.time} 分鐘</p></span>${icon('arrow')}</button>`).join('')}</div></div><aside class="daily-card"><span class="eyebrow">YOUR DAILY MOMENT</span><h3>今天的一句日文</h3><div class="daily-jp">${annotated('ありがとうございます。')}</div><p>謝謝你。</p><button class="listen-label" data-action="speak" data-text="ありがとうございます。">${icon('sound')} 聽聽怎麼說</button><hr><div class="goal-row"><span>今日小目標</span><b>${Math.min(n,state.goal)} / ${state.goal}</b></div><div class="progress-track"><i style="width:${Math.min(100,n/state.goal*100)}%"></i></div><small>每一次作答，都是前進一步。</small></aside></div><div class="gentle-note">${icon('leaf')} 不用完美才開始，開始了就會慢慢進步。<span>一緒に、少しずつ。</span></div>`;}
function courses(){return `${heading('LEARN THROUGH LIFE','把日文，放進生活裡。','五個小情境，從第一句到一段對話。依序學習，或從感興趣的主題開始。')}<div class="course-list">${lessons.map((l,i)=>`<button class="course-card" data-start="${l.id}"><div class="course-cover ${l.color}"><span class="course-num">LESSON 0${i+1}</span>${icon(l.icon)}<span class="course-ja">${['はじめまして','コーヒー','いくらですか','どこですか','好きです'][i]}</span></div><div class="course-info"><small>${l.category} · ${l.time} 分鐘</small><h2>${l.title}</h2><p>${l.desc}</p><div class="course-bottom"><span class="pill">${state.progress[l.id]?.complete?'✓ 已完成':state.progress[l.id]?'學習中':'初級入門'}</span>${icon('arrow')}</div></div></button>`).join('')}</div>`;}
function startLesson(id){stopSpeech();page='courses';lesson=lessons.find(l=>l.id===id);state.lastLesson=id;state.progress[id]??={step:0,complete:false};step=state.progress[id].step;question=0;answer=null;quizDone=false;selectedWords=new Set(lesson.words.map(w=>w.id));save();render();window.scrollTo(0,0);}
function lessonPage(){const names=['聽一聽','認識單字','看懂句型','換你試試','今天學會了'];return `<button class="back" data-nav="courses">← 所有課程</button><div class="lesson-heading"><div><p class="eyebrow">LESSON 0${lessons.indexOf(lesson)+1} · ${lesson.category}</p><h1>${lesson.title}</h1></div><span class="pill">${icon('clock')} 約 ${lesson.time} 分鐘</span></div><div class="steps">${names.map((n,i)=>`<button data-step="${i}" class="${step===i?'current':i<step?'past':''}" ${i>Math.max(step,state.progress[lesson.id]?.step||0)?'disabled':''}><span>${i<step?'✓':i+1}</span>${n}</button>`).join('')}</div><section class="lesson-body">${step===0?dialoguePage():step===1?wordsPage():step===2?grammarPage():step===3?practicePage():finishPage()}</section><div class="lesson-controls">${step>0?'<button class="secondary" data-action="prev">← 上一步</button>':'<span></span>'}${step<3?'<button class="primary" data-action="next">下一步 '+icon('arrow')+'</button>':''}</div>`;}
function dialoguePage(){return `<div class="section-title"><div><h2>先聽聽，他們怎麼說</h2><p class="muted">可以重複聽，也可以先關閉中文試試看。</p></div><button class="secondary" data-action="translation">${translate?'隱藏':'顯示'}中文</button></div><button class="listen-label" data-action="speak" data-text="${esc(lesson.dialogue.map(d=>d[1]).join(' '))}">${icon('sound')} 播放整段對話</button><div class="dialogue">${lesson.dialogue.map(([name,jp,zh],i)=>`<div class="dialogue-row ${name==='你'?'self':''}"><div class="speaker">${name==='你'?'你':name.slice(0,1)}</div><div class="bubble"><small>${name}</small><div class="jp-line">${annotated(jp)} ${playButton(jp)}</div>${translate?`<p>${zh}</p>`:''}</div></div>`).join('')}</div><div class="tip">${icon('leaf')} 小提示：先聽整段，再點擊單句的聲音，慢慢跟上節奏。</div>`;}
function wordsPage(){return `<h2>今天的 ${lesson.words.length} 個新朋友</h2><p class="muted">點擊單字查看例句，也可以收藏，留著下次查找。</p><div class="word-grid">${lesson.words.map(w=>`<div class="word-card"><button class="word-main" data-word="${w.id}">${ruby(w.jp,w.reading)}<small>${w.zh}</small></button>${playButton(w.reading)}<button class="save-word ${state.saved.includes(w.id)?'saved':''}" data-save="${w.id}" aria-label="${state.saved.includes(w.id)?'取消收藏':'收藏'}${w.jp}">${icon('star')}</button></div>`).join('')}</div><div class="tip">${icon('book')} 想一想：「${lesson.words[1].zh}」的日文怎麼說？點開卡片確認讀音。</div>`;}
function grammarPage(){return `<div class="section-title"><div><h2>一句話，一塊一塊看懂</h2><p class="muted">點擊句子中的詞語，了解它在這裡的作用。</p></div><button class="secondary" data-action="breakdown">${breakdown?'收起':'展開'}拆解</button></div><div class="sentence-box"><div class="sentence">${lesson.sentence.map(([jp,r,tag],i)=>`<button data-token="${i}" class="token token-${i%4}">${ruby(jp,r)}${breakdown?`<small>${tag}</small>`:''}</button>`).join('')}<span>。</span>${playButton(lesson.sentence.map(t=>t[0]).join('')+'。')}</div><p>${lesson.translation}</p></div><div class="pattern"><span class="eyebrow">帶走這個句型</span><h2 lang="ja">${lesson.pattern}</h2><p>${lesson.explain}</p></div><div class="tip">${icon('leaf')} 同一個助詞在不同句子裡，可能有不同作用。這裡先記住本句的用法。</div>`;}
function practicePage(){if(quizDone)return `<div class="empty"><span class="success-mark">${icon('check')}</span><h2>這一小步，完成了！</h2><p>你已經完成本課的三個練習。把重點留下來，之後再見一次。</p><button class="primary" data-action="next">查看學習成果 ${icon('arrow')}</button></div>`;const q=lesson.questions[question];const correct=answer===true;return `<div class="exercise"><div class="section-title"><span class="eyebrow">練習 ${question+1} / ${lesson.questions.length}</span><span class="pill">${{listen:'聽力理解',input:'句型填空',choice:'情境選答'}[q.type]}</span></div><h2>${q.q}</h2>${q.text?`<div class="exercise-text" lang="ja">${q.text}</div>`:''}${q.audio?`<button class="audio-prompt" data-action="speak" data-text="${esc(q.audio)}">${icon('sound')} 點擊聽題目</button>`:''}${q.type==='input'?`<form id="answer-form"><label for="answer-input">日文答案</label><div class="input-row"><input id="answer-input" autocomplete="off" placeholder="輸入假名" ${answer!==null?'disabled':''}><button class="primary" ${answer!==null?'disabled':''}>確認答案</button></div></form>`:`<div class="options">${q.options.map((o,i)=>`<button data-answer="${i}" ${answer!==null?'disabled':''} class="${answer!==null&&i===q.answer?'correct':''}"><span>${['A','B','C'][i]}</span>${esc(o)}</button>`).join('')}</div>`}${answer!==null?`<div class="feedback ${correct?'good':'retry'}"><strong>${correct?'✓ 答對了！':'再記住一次就好。'}</strong><p>${q.why}</p>${!correct?`<p>正確答案：${q.type==='input'?q.answer:q.options[q.answer]}</p>`:''}<button class="primary" data-action="next-question">${question===lesson.questions.length-1?'完成練習':'下一題'} ${icon('arrow')}</button></div>`:''}</div>`;}
function finishPage(){return `<div class="finish"><span class="success-mark">${icon('leaf')}</span><p class="eyebrow">小小成就，值得記住</p><h2>現在，你能${lesson.goal}了。</h2><p class="muted">把今天的重點加入複習，讓這份熟悉感留下來。</p><div class="finish-words">${lesson.words.map(w=>`<label><input type="checkbox" data-select-word="${w.id}" ${selectedWords.has(w.id)?'checked':''}>${ruby(w.jp,w.reading)}<small>${w.zh}</small></label>`).join('')}</div><button class="primary" data-action="complete">加入複習並完成 ${icon('check')}</button></div>`;}
function kanaPage(){const rows=kanaGroup==='combo'?comboRows:kanaRows.filter(r=>r.some(k=>k?.group===kanaGroup));return `${heading('THE SOUNDS OF JAPANESE','每一個聲音，都是起點。','點擊假名聽發音，再用小測驗練習辨認。')}${writingBanner()}<div class="kana-toolbar"><div class="segmented"><button data-kana-type="h" class="${kanaType==='h'?'selected':''}">平假名</button><button data-kana-type="k" class="${kanaType==='k'?'selected':''}">片假名</button></div><label class="check-label"><input type="checkbox" id="romaji" ${state.romaji?'checked':''}> 顯示羅馬字</label></div><div class="tabs">${[['basic','基本音'],['voiced','濁音・半濁音'],['combo','拗音']].map(([g,t])=>`<button data-kana-group="${g}" class="${kanaGroup===g?'selected':''}">${t}</button>`).join('')}</div><div class="kana-layout"><section class="kana-table"><div class="kana-vowels">${(kanaGroup==='combo'?['a','u','o']:['a','i','u','e','o']).map(v=>`<span>${v}</span>`).join('')}<span>練習</span></div>${rows.map((r,ri)=>`<div class="kana-row ${kanaGroup==='combo'?'combo':''}">${r.map(k=>k?`<button class="kana-cell ${state.kana[kanaType+k.h]?'learned':''} ${state.writing[k[kanaType]]?'has-writing':''}" data-kana="${k.h}" aria-label="${k[kanaType]}，點擊發音"><span lang="ja">${k[kanaType]}</span>${state.romaji?`<small>${k.r}</small>`:''}</button>`:'<div class="kana-blank"></div>').join('')}<button class="row-practice" data-kana-quiz="${ri}" aria-label="練習這一行">${icon('arrow')}</button></div>`).join('')}</section><aside class="kana-guide"><span class="tile-icon sand kana-icon">あ</span><h3>先聽，再跟著念。</h3><p>點擊任一假名，看看例詞。基本假名可進入手寫練習；右邊的箭頭是聽音測驗。</p><hr><h4>長音</h4><p>把母音延長一拍：<button class="inline-sound" data-action="speak" data-text="おばさん。おばあさん。">おばさん / おばあさん ${icon('sound')}</button></p><h4>促音「っ」</h4><p>小小的「っ」占一拍，短暫停頓：<button class="inline-sound" data-action="speak" data-text="きて。きって。">きて / きって ${icon('sound')}</button></p><h4>撥音「ん」</h4><p>「ん」也占一拍，例如「ほん」是兩拍。</p><small>語音為裝置合成；單音與自然句子的聲音可能略有不同。</small></aside></div>`;}
function writingBanner(){const list=Object.values(state.writing);const trace=list.filter(p=>p.trace>0).length,free=list.filter(p=>p.free>0).length;const last=state.lastWriting[kanaType],char=last||(kanaType==='h'?'あ':'ア');return `<div class="writing-banner"><span class="writing-symbol" aria-hidden="true">${char}</span><div><h3>用手寫，記住每個假名。</h3><p>點選下方字卡，再按「練習手寫」就能練指定的字。基本假名共 92 字。</p><div class="writing-stats"><span>描寫過 ${trace} 字</span><span>自由書寫過 ${free} 字</span></div></div><button class="primary" data-writing="${char}">${last?'繼續上次手寫「'+char+'」':'開始手寫練習「'+char+'」'} →</button></div>`;}
function startWriting(char){if(!hasHandwriting(char))return;const scrollY=window.scrollY,fromCard=$('#detail').open;stopSpeech();$('#detail').close();const type=char.charCodeAt(0)<0x30a0?'h':'k',sequence=kanaRows.flat().filter(k=>k?.group==='basic').map(k=>k[type]);const remember=c=>{state.lastWriting[type]=c;save();};remember(char);openHandwriting({char,sequence,speak,getProgress:c=>state.writing[c],onChoose:remember,onComplete:(c,mode)=>{state.writing[c]??={trace:0,free:0,lastAt:''};state.writing[c][mode]++;state.writing[c].lastAt=today();activity();},onClose:()=>{stopSpeech();render();const key=type==='h'?char:String.fromCharCode(char.charCodeAt(0)-96);document.querySelector(fromCard?`[data-kana="${key}"]`:'.writing-banner [data-writing]')?.focus({preventScroll:true});window.scrollTo({top:scrollY,behavior:'instant'});}});}
function detail(html){const d=$('#detail');d.innerHTML=`<button class="dialog-close" data-action="close" aria-label="關閉">${icon('close')}</button>${html}`;if(!d.open)d.showModal();}
function showWord(id){const w=allWords.find(w=>w.id===id);detail(`<span class="eyebrow">單字小筆記</span><h2 class="detail-word">${ruby(w.jp,w.reading)}</h2><p>${w.zh}</p>${playButton(w.reading)}<div class="pattern"><small>放進句子裡</small><p class="jp-line">${annotated(w.example)}</p>${playButton(w.example)}</div><button class="secondary" data-save="${id}">${state.saved.includes(id)?'★ 已收藏':'☆ 收藏單字'}</button>`);}
function showKana(h){const k=[...kanaRows.flat(),...comboRows.flat()].find(k=>k?.h===h),char=k[kanaType],p=state.writing[char];detail(`<span class="eyebrow">${kanaType==='h'?'平假名':'片假名'}</span><div class="big-kana" lang="ja">${char} <span>${k[kanaType==='h'?'k':'h']}</span></div><p>${k.r}</p><div class="kana-card-actions"><button class="secondary" data-action="speak" data-text="${k.h}">${icon('sound')} 聽發音</button>${hasHandwriting(char)?`<button class="primary" data-writing="${char}">練習手寫「${char}」 →</button>`:''}</div>${hasHandwriting(char)?`<p class="writing-status">描寫 ${p?.trace||0} 次 · 自由書寫 ${p?.free||0} 次</p><p class="muted small">直接從「${char}」開始，看筆順、跟著描，再試著自己寫。</p>`:'<p class="muted small">手寫練習目前提供 92 個基本假名，可切換到「基本音」開始。</p>'}${k.example?`<div class="pattern"><small>例詞</small><h2 lang="ja">${k.example[0]}</h2><p>${k.example[1]}</p>${playButton(k.example[0])}</div>`:'<p class="muted">拗音由前面的假名與小寫的「ゃ・ゅ・ょ」組成，合起來算一拍。</p>'}`);speak(k.h);}

function startKanaQuiz(ri){const rows=kanaGroup==='combo'?comboRows:kanaRows.filter(r=>r.some(k=>k?.group===kanaGroup));const pool=rows[ri].filter(Boolean);const all=rows.flat().filter(Boolean);const questions=Array.from({length:5},(_,i)=>{const target=pool[i%pool.length];const others=all.filter(k=>k.h!==target.h).sort(()=>Math.random()-.5).slice(0,3);return {target,options:[target,...others].sort(()=>Math.random()-.5)};});kanaQuiz={questions,index:0,score:0,answered:false};renderKanaQuiz();}
function renderKanaQuiz(){const z=kanaQuiz;if(z.index===5){detail(`<div class="empty"><span class="success-mark">${icon('check')}</span><h2>練習完成！</h2><p>這次答對 ${z.score} / 5 題。</p><p>答對的假名已標記在字表上，隨時可以再練習。</p><button class="primary" data-action="close">回到五十音</button></div>`);render();return;}const q=z.questions[z.index];detail(`<span class="eyebrow">聽音選假名 ${z.index+1} / 5</span><h2>你聽到哪一個聲音？</h2><button class="audio-prompt" data-action="speak" data-text="${q.target.h}">${icon('sound')} 播放題目</button><div class="kana-options">${q.options.map(k=>`<button data-kana-answer="${k.h}" ${z.answered?'disabled':''} class="${z.answered&&k.h===q.target.h?'correct':''}">${k[kanaType]}</button>`).join('')}</div>${z.answered?`<div class="feedback"><p>${z.correct?'✓ 答對了！':`正確答案是「${q.target[kanaType]}」。再聽一次記住它。`}</p><button class="primary" data-action="next-kana">${z.index===4?'查看結果':'下一題'}</button></div>`:''}`);}
function reviewPage(){if(!review){const count=dueIds().length,total=Object.keys(state.cards).length;return `${heading('MAKE IT STAY','再見一次，就更熟悉一點。','先回想，再翻開答案。依照你的記憶狀況，安排下一次相遇。')}<div class="review-start"><span class="review-illustration">${icon('repeat')}</span><h2>${count?`今天有 ${count} 個詞語等著你。`:total?'今天的複習已經完成。':'讓學過的詞語，在這裡相遇。'}</h2><p>${count?'每次最多練習 10 張卡片，慢慢來就好。':total?'下次到期時，它們會再次出現。也可以繼續學習新的課程。':'完成一個情境課程，就能把重點加入複習。'}</p>${count?`<button class="primary" data-action="start-review">開始複習 ${icon('arrow')}</button>`:'<button class="primary" data-nav="courses">去學一課 '+icon('arrow')+'</button>'}<small>複習庫共有 ${total} 個詞語</small></div>`;}if(!review.queue.length)return `<div class="empty review-start"><span class="success-mark">${icon('check')}</span><h1>今天又更熟悉一點了。</h1><p>這一組完成了 ${review.count} 次回想。已依照你的作答安排下一次複習。</p><button class="primary" data-nav="review">返回複習總覽</button></div>`;const w=allWords.find(w=>w.id===review.queue[0]);return `<div class="review-top"><button class="back" data-nav="review">← 稍後繼續</button><span>剩餘 ${review.queue.length} 張 · 已回想 ${review.count} 次</span></div><div class="flashcard"><span class="eyebrow">${lessons.find(l=>l.id===w.lesson).short}</span><h1>${flipped?ruby(w.jp,w.reading):esc(w.jp)}</h1>${playButton(w.reading)}${flipped?`<h2>${w.zh}</h2><p class="jp-line">${annotated(w.example)}</p>${playButton(w.example)}<p class="muted">這個詞，你記得多清楚？</p><div class="rating"><button data-rate="again">還不熟<small>稍後再練</small></button><button data-rate="hard">想了一下<small>較快再見</small></button><button data-rate="good">記得<small>延長間隔</small></button></div>`:'<p class="muted">先想一想，它是什麼意思？</p><button class="primary" data-action="flip">顯示答案</button>'}</div>`;}
function mine(){refreshVoices();return `${heading('YOUR LEARNING GARDEN','照自己的步調，慢慢長大。','收藏喜歡的詞語，也把學習方式調整成適合自己的樣子。')}<div class="settings-grid"><section class="panel"><h2>學習偏好</h2><label class="setting-row">每日作答目標<select id="goal">${[5,10,15].map(n=>`<option value="${n}" ${state.goal===n?'selected':''}>${n} 次</option>`).join('')}</select></label><label class="setting-row">合成語音速度<select id="rate">${[[.65,'慢速'],[.85,'稍慢'],[1,'自然']].map(([v,n])=>`<option value="${v}" ${state.rate===v?'selected':''}>${n}</option>`).join('')}</select></label><label class="setting-row">日文聲音<select id="voice"><option value="">自動選擇</option>${voices.map(v=>`<option value="${esc(v.voiceURI)}" ${state.voice===v.voiceURI?'selected':''}>${esc(v.name)}</option>`).join('')}</select></label><p class="small muted">${voices.length?`已找到 ${voices.length} 個日文合成聲音。`:'目前裝置未提供日文聲音，請安裝系統日文語音或換用其他瀏覽器。'}聲音選項由你的裝置提供。</p><button class="secondary" data-action="speak" data-text="こんにちは。今日も一緒に日本語を勉強しましょう。">${icon('sound')} 試聽聲音</button></section><section class="panel"><h2>學習進度與備份</h2><p>進度保存在目前的瀏覽器。更換裝置或清除瀏覽資料前，可以先匯出備份。</p><div class="backup-status"><span class="dot"></span>${storageOK?'瀏覽器儲存可用':'目前無法保存，請匯出備份'}</div><div class="button-row"><button class="secondary" data-action="export">匯出進度</button><button class="secondary" data-action="import">匯入進度</button><input type="file" id="import-file" accept="application/json,.json" hidden></div><p class="small muted">匯入前會顯示內容供你確認，並提供現有進度備份。</p></section></div><div class="section-title lower"><h2>我的收藏 <span class="count">${state.saved.length}</span></h2></div>${state.saved.length?`<div class="word-grid">${state.saved.map(id=>{const w=allWords.find(w=>w.id===id);return `<div class="word-card"><button class="word-main" data-word="${id}">${ruby(w.jp,w.reading)}<small>${w.zh}</small></button>${playButton(w.reading)}<button class="save-word saved" data-save="${id}" aria-label="取消收藏${w.jp}">${icon('star')}</button></div>`;}).join('')}</div>`:'<div class="empty small-empty"><span class="tile-icon sand">'+icon('star')+'</span><h3>把喜歡的詞語，留在這裡。</h3><p>在課程的單字卡上點擊星星，就能隨時回來查看。</p><button class="text-link" data-nav="courses">探索情境課程 '+icon('arrow')+'</button></div>'}`;}
function moveStep(n){stopSpeech();step=Math.max(0,Math.min(4,n));state.progress[lesson.id]={...state.progress[lesson.id],step};save();render();window.scrollTo(0,0);}
function checkAnswer(v){if(answer!==null)return;const q=lesson.questions[question];answer=q.type==='input'?v.trim().normalize('NFKC').replace(/[\s。]/g,'')===q.answer:Number(v)===q.answer;activity();render();}
let pendingImport=null;
function exportProgress(){const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`hiyori-progress-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
document.addEventListener('click',e=>{const b=e.target.closest('button,a[data-nav]');if(!b)return;if(b.dataset.nav){e.preventDefault();nav(b.dataset.nav);return;}if(b.dataset.writing){startWriting(b.dataset.writing);return;}if(b.dataset.start){startLesson(b.dataset.start);return;}if(b.dataset.word){showWord(b.dataset.word);return;}if(b.dataset.save){const id=b.dataset.save;state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];save();toast(state.saved.includes(id)?'已加入收藏':'已取消收藏');render();if($('#detail').open)showWord(id);return;}if(b.dataset.token!==undefined){const [jp,r,tag,ex]=lesson.sentence[+b.dataset.token];detail(`<span class="eyebrow">${tag}</span><h2 class="detail-word">${ruby(jp,r)}</h2><p>${ex}</p>${playButton(jp==='は'?'わ':jp==='を'?'お':r||jp)}`);return;}if(b.dataset.step!==undefined){moveStep(+b.dataset.step);return;}if(b.dataset.answer!==undefined){checkAnswer(b.dataset.answer);return;}if(b.dataset.kanaType){kanaType=b.dataset.kanaType;render();return;}if(b.dataset.kanaGroup){kanaGroup=b.dataset.kanaGroup;render();return;}if(b.dataset.kana){showKana(b.dataset.kana);return;}if(b.dataset.kanaQuiz!==undefined){startKanaQuiz(+b.dataset.kanaQuiz);return;}if(b.dataset.kanaAnswer){if(kanaQuiz.answered)return;kanaQuiz.answered=true;kanaQuiz.correct=b.dataset.kanaAnswer===kanaQuiz.questions[kanaQuiz.index].target.h;if(kanaQuiz.correct){kanaQuiz.score++;state.kana[kanaType+b.dataset.kanaAnswer]=true;}activity();renderKanaQuiz();return;}if(b.dataset.rate){if(!review?.queue.length||!flipped)return;const id=review.queue.shift(),c=state.cards[id],r=b.dataset.rate;if(r==='again'){c.interval=0;c.due=Date.now()+60000;review.queue.push(id);}else{c.interval=r==='hard'?Math.max(1,Math.round(c.interval*1.2)):Math.min(365,Math.max(1,Math.round(c.interval*2.4)));c.due=Date.now()+c.interval*86400000;}c.reps++;review.count++;flipped=false;activity();render();return;}switch(b.dataset.action){case'speak':speak(b.dataset.text,b);break;case'close':$('#detail').close();stopSpeech();break;case'translation':translate=!translate;render();break;case'breakdown':breakdown=!breakdown;render();break;case'next':moveStep(step+1);break;case'prev':moveStep(step-1);break;case'next-question':question++;answer=null;if(question>=lesson.questions.length)quizDone=true;render();break;case'next-kana':kanaQuiz.index++;kanaQuiz.answered=false;renderKanaQuiz();break;case'complete':for(const id of selectedWords){if(!state.cards[id])state.cards[id]={due:Date.now(),interval:0,reps:0};}state.progress[lesson.id]={step:4,complete:true};activity();const next=lessons[lessons.indexOf(lesson)+1];if(next)state.lastLesson=next.id;save();nav('today');toast('課程完成！選定詞語已加入複習。');break;case'start-review':review={queue:dueIds().slice(0,10),count:0};flipped=false;render();break;case'flip':flipped=true;render();break;case'export':exportProgress();break;case'import':$('#import-file').click();break;case'confirm-import':state=pendingImport;save();$('#detail').close();render();toast('進度已匯入');break;}});
document.addEventListener('submit',e=>{if(e.target.id==='answer-form'){e.preventDefault();checkAnswer($('#answer-input').value);}});
document.addEventListener('change',async e=>{const t=e.target;if(t.id==='furigana'){state.furigana=t.value;save();document.body.dataset.furigana=t.value;}if(t.id==='romaji'){state.romaji=t.checked;save();render();}if(['rate','goal','voice'].includes(t.id)){state[t.id]=t.id==='voice'?t.value:Number(t.value);save();}if(t.dataset.selectWord){if(t.checked)selectedWords.add(t.dataset.selectWord);else selectedWords.delete(t.dataset.selectWord);}if(t.id==='import-file'&&t.files[0]){try{if(t.files[0].size>1000000)throw Error('檔案過大，請選擇日和日語匯出的進度檔');pendingImport=validate(JSON.parse(await t.files[0].text()));detail(`<h2>匯入這份進度？</h2><p>包含 ${Object.keys(pendingImport.progress).length} 課進度、${Object.keys(pendingImport.cards).length} 個複習詞語及 ${pendingImport.saved.length} 個收藏，以及 ${Object.keys(pendingImport.writing).length} 字的手寫紀錄。</p><p>匯入後會取代目前進度。你可以先下載目前的備份。</p><div class="button-row"><button class="secondary" data-action="export">先備份目前進度</button><button class="primary" data-action="confirm-import">確認匯入</button></div>`);}catch(err){toast('匯入失敗：'+err.message);}t.value='';}});
$('#detail').addEventListener('click',e=>{if(e.target===$('#detail')){$('#detail').close();stopSpeech();}});
$('#detail').addEventListener('cancel',()=>stopSpeech());
document.addEventListener('click',e=>{const r=e.target.closest('.reading');if(r)r.classList.toggle('revealed');});
render();
